def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx, *args, **kwargs):
            try:
                if metadata:
                    tx.metadata = metadata
                if timeout is not None:
                    if timeout < 0:
                        raise ValueError("Timeout should not be a negative duration")
                    tx.timeout = timeout
                result = func(tx, *args, **kwargs)
                return result
            except Exception as e:
                raise Exception(f"Transaction failed: {e}")
        return wrapper
    return decorator

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not hasattr(self, '_record'):
        raise ValueError("Record object has not been initialized")

    if not keys:
        return list(self._record.values())

    val = []
    for k in keys:
        if isinstance(k, int):
            if k in self._record:
                val.append(self._record[k])
        elif isinstance(k, str):
            if k in self._record:
                val.append(self._record[k])
        else:
            raise ValueError(f"Invalid key type: {type(k)}")

    return val

