def point_type(name, fields, srid_map):
    try:
        field_attributes = {}
        for field, details in fields.items():
            field_type = details.get('type')
            if field_type == 'INT':
                field_attributes[field] = int
            elif field_type == 'FLOAT':
                field_attributes[field] = float
            elif field_type == 'STR':
                field_attributes[field] = str
            else:
                raise ValueError(f"Unsupported field type: {field_type}")

        class PointSubclass(Point, **field_attributes):
            def __init__(self, x, y, srid, **kwargs):
                self.x = x
                self.y = y
                self.srid = srid
                for key, value in kwargs.items():
                    setattr(self, key, value)

            @property
            def srid(self):
                return self._srid

            @srid.setter
            def srid(self, value):
                if value in srid_map:
                    self._srid = value
                else:
                    raise ValueError(f"Invalid SRID: {value}")

        return PointSubclass
    except Exception as e:
        print(f"Error creating Point subclass: {e}")
        return None
