        sentinel = object()
        def wrapper(*args):
            if typed:
                key = (func, args, args[1:] if len(args) > 1 else ())
            else:
                key = (func, tuple(args) if not isinstance(args[0], tuple) else args[0])
            if key not in cache:
                cache[key] = (func(*args), time.time())
            else:
                result, last_used = cache[key]
                cache[key] = (result, time.time())
