def cachedmethod(cache, key=hash, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def wrapper(func):
        @functools.wraps(func)
        def memoized_method(self, *args, **kwargs):
            if lock is not None:
                lock.acquire()
            try:
                if (self, args, tuple(kwargs.items())) not in cache:
                    cache[(self, args, tuple(kwargs.items()))] = func(self, *args, **kwargs)
            finally:
                if lock is not None:
                    lock.release()
            return cache[(self, args, tuple(kwargs.items()))]
        return memoized_method
    return wrapper
