import traceback

class ExceptionFormatter:
    @classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        try:
            formatted_traceback = traceback.format_exception(type(e), e, e.__traceback__)
            rows = formatted_traceback.split('\n')
            filtered_rows = []
            path_level = 0

            for row in rows:
                if row.startswith('  File'):
                    path_level += 1
                    if path_level > max_path_level:
                        continue
                elif row.startswith('    '):
                    path_level -= 1
                filtered_rows.append(row)

            return '\n'.join(filtered_rows[:max_level + 1])
        except Exception as ex:
            return f"Error formatting exception: {ex}"
