def _update_context(self, context):
    if not isinstance(context, dict):
        raise ValueError("context must be a dictionary")

    if 'error' not in context:
        context['error'] = {}

    if not isinstance(context['error'], dict):
        raise ValueError("context['error'] must be a dictionary")

    for field in self.fields:
        if field.startswith('error_'):
            error_name = field[6:]
            if error_name == 'x':
                error_key = 'x_low'
            elif error_name == 'y':
                error_key = 'y_low'
            elif error_name == 'z':
                error_key = 'z_low'
            else:
                raise ValueError(f"invalid error field: {field}")

            if 'error' not in context:
                context['error'] = {}
            if error_key not in context['error']:
                context['error'][error_key] = {'index': None}
            if self.errors.get(field) is not None:
                context['error'][error_key]['index'] = self.errors[field]

    if 'value' not in context:
        context['value'] = {}

    if not isinstance(context['value'], dict):
        raise ValueError("context['value'] must be a dictionary")

    # Assuming self.values is a dictionary of graph values
    for key, value in self.values.items():
        if key not in context['value']:
            context['value'][key] = value
        else:
            context['value'][key].update(value)

