import copy

def difference(d1, d2, level=-1):
    result = {}
    if level == 0:
        return result

    for k, v1 in d1.items():
        if k not in d2:
            result[k] = copy.deepcopy(v1)
        elif isinstance(v1, dict) and isinstance(d2[k], dict):
            diff = difference(v1, d2[k], level - 1 if level > 0 else level)
            if diff:
                result[k] = diff
        elif v1 != d2[k]:
            result[k] = copy.deepcopy(v1)

    return result
