def generate_default_observer_schema(app):
    # Initialize a dictionary to store the default observer schemas for each Kubernetes resource
    default_schemas = {}

    # Iterate through each resource in the application's manifest
    for resource in app.manifest.get("resources", []):
        # Extract the resource kind and group
        kind = resource.get("kind")
        apiGroup = resource.get("apiVersion", "").split("/")[0]

        # Generate the default observer schema for the resource
        default_schema = {
            "kind": kind,
            "apiVersion": apiGroup,
            "metadata": {
                "name": "{{ .metadata.name }}"
            },
            "spec": {
                # Add default spec fields based on the resource kind
                "field1": "{{ .spec.field1 }}",
                "field2": "{{ .spec.field2 }}"
            }
        }

        # Store the default schema for the resource
        default_schemas[f"{apiGroup}/{kind}"] = default_schema

    return default_schemas
