def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if not isinstance(sql, (str, bytes)):
        raise ValueError("sql must be a string or bytes")
    if not isinstance(many_params, (list, tuple)):
        raise ValueError("many_params must be a list or tuple")

    formatted_sql = sql
    converted_params = []

    for params in many_params:
        if isinstance(params, dict):
            converted_params.append(self.formatparams(params, "out"))
        elif isinstance(params, (list, tuple)):
            converted_params.append(self.formatparams(params, "out"))
        else:
            raise ValueError("params must be a dict or sequence")

    return formatted_sql, converted_params
