            return False

        manifest_path = os.path.join(path, 'manifest.json')
        with open(manifest_path, 'r') as f:
            manifest = json.load(f)
            if not isinstance(manifest, dict) or 'objects' not in manifest:
                return False

            for obj_id, obj_info in manifest['objects'].items():
                if not isinstance(obj_id, str) or not isinstance(obj_info, dict):
                    return False

                object_path = os.path.join(path, obj_id)
                if not os.path.isdir(object_path):
                    return False

                versions_path = os.path.join(object_path, 'versions')
                if not os.path.isdir(versions_path):
                    return False

                version_dir_list = os.listdir(versions_path)
                for version_dir in version_dir_list:
                    version_path = os.path.join(versions_path, version_dir)
                    if not os.path.isdir(version_path):
                        return False

                    inventory_path = os.path.join(version_path, 'inventory.json')
                    with open(inventory_path, 'r') as f:
                        inventory = json.load(f)
                        if not isinstance(inventory, dict) or 'manifest' not in inventory:
                            return False

                        for file_path, file_info in inventory['manifest'].items():
                            if not isinstance(file_path, str) or not isinstance(file_info, dict):
                                return False

                            file_hash = os.path.join(version_path, file_info['location'])
                            if not os.path.isfile(file_hash):
                                return False

                            with open(file_hash, 'rb') as f:
                                file_data = f.read()
                                if file_info['hash'] != hashlib.sha256(file_data).hexdigest():
                                    return False

        return True
    except Exception as e:
        print(f"Validation error: {e}")
        return False
