import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not commands or not args:
        raise ValueError("Both commands and args must be provided")

    try:
        if hide_stderr:
            process = subprocess.Popen([commands] + args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
        else:
            process = subprocess.Popen([commands] + args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)

        stdout, stderr = process.communicate()

        if verbose:
            print(f"Stdout: {stdout.decode('utf-8')}")

        if process.returncode != 0 and not hide_stderr:
            raise subprocess.CalledProcessError(process.returncode, command=[commands] + args, output=stdout, stderr=stderr)

        return stdout.decode('utf-8')

    except Exception as e:
        raise RuntimeError(f"Error running command {commands} with args {args}: {e}") from e
