def deep_merge_nodes(nodes):
    def is_mapping_node(node):
        return isinstance(node, ruamel.yaml.nodes.MappingNode)

    def merge_two_nodes(key_node, value_node1, value_node2):
        if is_mapping_node(value_node1) and is_mapping_node(value_node2):
            merged_value = {key_node.value: value_node1.value}
            for scalar_node, node in value_node2.value:
                if scalar_node.value in merged_value:
                    if is_mapping_node(node):
                        merged_value[scalar_node.value] = merge_two_nodes(scalar_node, merged_value[scalar_node.value], node)
                    else:
                        merged_value[scalar_node.value] = node
                else:
                    merged_value[scalar_node.value] = node
            return type(value_node1)(tag=value_node1.tag, value=merged_value)
        else:
            return value_node2

    merged_nodes = {}
    for key_node, value_node in nodes:
        if key_node.value in merged_nodes:
            merged_nodes[key_node.value] = merge_two_nodes(key_node, merged_nodes[key_node.value], value_node)
        else:
            merged_nodes[key_node.value] = value_node

    return [(key_node, merged_nodes[key_node.value]) for key_node in merged_nodes]
