def deep_merge_nodes(nodes):
    from borgmatic.config.common import merge_mappings
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    merged_nodes = {}
    for key_node, value_node in nodes:
        if not isinstance(key_node, ScalarNode) or not isinstance(value_node, (MappingNode, ScalarNode)):
            raise ValueError("Invalid node type in input")

        key = key_node.value
        if key not in merged_nodes:
            merged_nodes[key] = []

        if isinstance(value_node, MappingNode):
            merged_nodes[key].append((key_node, value_node))
        else:
