def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    import os
    import tempfile
    import tarfile
    from pathlib import Path

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive path '{archive_path}' does not exist.")

    # Ensure tmp_path is a Path object
    if isinstance(tmp_path, str):
        tmp_path = Path(tmp_path)

    # Create a temporary directory to extract the archive
    with tempfile.TemporaryDirectory(dir=tmp_path) as temp_dir:
        # Extract the archive
        if filename is None:
            filename = Path(archive_path).name
        archive_full_path = Path(archive_path) / filename
        if not archive_full_path.exists():
            raise FileNotFoundError(f"Archive file '{filename}' not found in '{archive_path}'.")

        if archive_full_path.suffix == '.tar.gz' or archive_full_path.suffix == '.tgz':
            with tarfile.open(archive_full_path, 'r:gz') as tar:
                tar.extractall(path=temp_dir)
        elif archive_full_path.suffix == '.zip':
            with zipfile.ZipFile(archive_full_path, 'r') as zip_ref:
                zip_ref.extractall(temp_dir)
        else:
            raise ValueError(f"Unsupported archive type: {archive_full_path.suffix}")

        # Return the file repo url (Assuming the extracted directory is the repo)
        repo_path = Path(temp_dir) / filename[:-len(archive_full_path.suffix)]
        return str(repo_path)

