import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, list):
        raise ValueError("commands must be a list")
    if not isinstance(args, list):
        raise ValueError("args must be a list")

    command = [commands[0]] + args

    try:
        process = subprocess.Popen(command, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)

        stdout, stderr = process.communicate()

        if verbose:
            if not hide_stderr and stderr:
                printstderr(stderr.decode('utf-8'))
            if stdout:
                printstdout(stdout.decode('utf-8'))

        return process.returncode, stdout.decode('utf-8'), stderr.decode('utf-8')

    except FileNotFoundError:
        raise FileNotFoundError(f"Command not found: {commands[0]}")
    except PermissionError:
        raise PermissionError(f"Permission denied for command: {commands[0]}")
    except Exception as e:
        raise Exception(f"An error occurred while running the command: {str(e)}")

def printstdout(stdout):
