from rdflib import Graph, URIRef, Node
from typing import Optional, Set

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    for s, p, o in graph:
        if p != prop:
            continue
        if o not in roots:
            roots.add(o)
        if s not in roots:
            roots.add(s)
        if s in graph.subjects(predicate=prop):
            roots.discard(s)

    return roots
