            logging.error(f"Configuration file not found: {filename}")
            parse_errors.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, "Configuration file not found: %s", (filename,), None))
        except json.JSONDecodeError:
            logging.error(f"Error decoding JSON from file: {filename}")
            parse_errors.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, "Error decoding JSON from file: %s", (filename,), None))
