from datetime import datetime, timedelta, timezone
from dateutil import parser
from dateutil.relativedelta import relativedelta
import pytz

def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    if not isinstance(timestr, str):
        raise TypeError("Input must be a string")

    try:
        result = parser.parse(timestr, **kwargs)
    except (ValueError, OverflowError) as e:
        raise ParserError(f"Invalid date format: {timestr}") from e

    if default is not None and isinstance(default, datetime):
        result = default.replace(
            year=result.year,
            month=result.month,
            day=result.day,
            hour=result.hour,
            minute=result.minute,
            second=result.second,
            microsecond=result.microsecond,
        )

    if ignoretz:
        result = result.replace(tzinfo=None)

    if tzinfos:
        tz_name = result.tzinfo.tzname(result)[0] if result.tzinfo else None
        if tz_name in tzinfos:
            tz_info = tzinfos[tz_name]
            if isinstance(tz_info, int):
                tz_info = timezone(timedelta(seconds=tz_info))
            elif not isinstance(tz_info, timezone):
                raise TypeError("Time zone info must be an int or timezone object")
            result = result.replace(tzinfo=tz_info)

    return result
