import requests
from bs4 import BeautifulSoup

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    if not isinstance(handle, str) or "@" not in handle:
        raise ValueError("Invalid handle format")

    url = f"https://{handle}/.well-known/webfinger?resource={handle}"
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.RequestException as e:
        raise Exception("Failed to retrieve webfinger document") from e

    soup = BeautifulSoup(response.text, 'html.parser')
    data = {}
    for link in soup.find_all('link', rel='http://microformats.org/profile/hcard'):
        for attr, value in link.attrs.items():
            if attr.startswith('data-'):
                data[attr] = value

    if not data:
        raise Exception("No data found in webfinger document")

    return data
