def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise ValueError("Invalid input: parser_dict must be a dictionary")

    if "include" not in parser_dict or not isinstance(parser_dict["include"], dict):
        return parser_dict

    include_dict = parser_dict["include"]
    for key, include_path in include_dict.items():
        if not isinstance(key, str) or not isinstance(include_path, str):
            raise ValueError("Invalid include dictionary: keys and values must be strings")

        try:
            with open(include_path, 'r') as file:
                include_content = file.read()
                include_dict[key] = include_content
        except FileNotFoundError:
            raise FileNotFoundError(f"Include file not found: {include_path}")
        except Exception as e:
            raise Exception(f"Error reading include file {include_path}: {e}")

    return parser_dict
