def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Assuming required_args is a set of tuples where each tuple contains the argument name and a boolean indicating if it is required.
    required_args = {
        ("arg1", True),
        ("arg2", True),
        ("arg3", False)
    }

    provided_args = set(args.keys())

    for arg, required in required_args:
        if required and arg not in provided_args:
            raise ValueError(f"Required argument '{arg}' not provided.")

    return True

