def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :raises ValueError: If any argument is outside the valid range.
    """
    if args is None:
        raise ValueError("Arguments cannot be None")

    for arg in args:
        if not isinstance(arg, (int, float)):
            raise ValueError("All arguments must be numbers")

        min_val = getattr(self, f"min_{arg}")
        max_val = getattr(self, f"max_{arg}")
        if not min_val <= arg <= max_val:
            raise ValueError(f"Argument {arg} is out of range. Must be between {min_val} and {max_val}")
